#!/usr/bin/php
<?php
/** Local-only Asterisk AGI adapter. No outbound dialing or real patient lookup. */
require_once dirname(__DIR__,2).'/inc/connect.php';
require_once dirname(__DIR__,2).'/inc/ivr_service.php';

$agi=[];
while(($line=fgets(STDIN))!==false){$line=trim($line);if($line==='')break;$pair=explode(':',$line,2);if(count($pair)===2)$agi[trim($pair[0])]=trim($pair[1]);}
function agi(string $command):string{fwrite(STDOUT,$command."\n");fflush(STDOUT);$result=fgets(STDIN);return $result===false?'':trim($result);}
function prompt_file(PDO $db,string $key,string $language):string{$q=$db->prepare('SELECT audio_path FROM ivr_voice_prompts WHERE prompt_key=? AND language=? AND is_active=1');$q->execute([$key,$language]);$path=(string)($q->fetchColumn()?:'');if($path===''||!str_starts_with($path,'assets/ivr-prompts/'))return 'beep';$full=dirname(__DIR__,2).'/'.$path;if(!is_file($full)||strtolower(pathinfo($full,PATHINFO_EXTENSION))!=='wav')return 'beep';return preg_replace('/\.wav$/i','',$full)?:'beep';}
function get_digit(PDO $db,string $key,string $language,int $timeout=9000):string{$file=prompt_file($db,$key,$language);$response=agi('GET DATA '.$file.' '.$timeout.' 1');if(preg_match('/result=(-?\d+)/',$response,$m)){if($m[1]==='-1'){$GLOBALS['ivr_channel_hungup']=true;return '';}return $m[1]==='0'?'':$m[1];}return '';}
function event(PDO $db,int $callId,string $type,string $menu,?string $value,array $payload=[]):void{ivr_log_event($db,$callId,$type,$menu,$value,$payload);}

$uniqueId=preg_replace('/[^A-Za-z0-9]/','',(string)($agi['agi_uniqueid']??bin2hex(random_bytes(8))));
$caller='TEST-SIP-'.substr(hash('sha256',$uniqueId),0,12);
$operator=(int)(getenv('MCARE_IVR_OPERATOR_ID')?:0);$operator=$operator>0?$operator:null;
$db->beginTransaction();$limitQuery=$db->prepare("SELECT config_value FROM ivr_test_config WHERE config_key='max_concurrent_calls' FOR UPDATE");$limitQuery->execute();$limit=max(1,min(100,(int)($limitQuery->fetchColumn()?:10)));$activeCount=(int)$db->query("SELECT COUNT(*) FROM ivr_calls WHERE is_test=1 AND status IN ('active','queued','answered_simulated')")->fetchColumn();$callUuid=generate_uuid();$status=$activeCount>=$limit?'failed':'active';$state=$activeCount>=$limit?'failed':'welcome';$db->prepare("INSERT INTO ivr_calls(call_uuid,call_source,is_test,caller_number,caller_fixture,state,current_menu,status,created_by,error_message,ended_at,duration_seconds) VALUES(?,'asterisk_local',1,?,'synthetic_anonymous',?,'welcome',?,?,?,IF(?='failed',NOW(),NULL),IF(?='failed',0,NULL))")->execute([$callUuid,$caller,$state,$status,$operator,$activeCount>=$limit?'Configured test-call capacity reached':null,$status,$status]);$callId=(int)$db->lastInsertId();if($status==='failed'){event($db,$callId,'call_rejected_capacity','welcome',(string)$limit,['message'=>'Configured development test-call capacity reached.']);$db->commit();agi('HANGUP');exit(0);}event($db,$callId,'call_started','welcome',$caller,['message'=>'TEST SIP call accepted from a local-only test extension.']);$db->commit();
agi('ANSWER');agi('VERBOSE "M-CARE TEST IVR call '.$callId.'; no external routing" 1');
$language='en';$ended=false;
try{
    $digit=get_digit($db,'welcome','en');
    if($digit==='1')$language='rw';elseif($digit!=='2'){$ended=true;}
    if(!$ended){$db->prepare("UPDATE ivr_calls SET language=?,state='main_menu',current_menu='main' WHERE ivr_call_id=?")->execute([$language,$callId]);event($db,$callId,'language_selected','welcome',$language);
        for($turn=0;$turn<60;$turn++){
            $digit=get_digit($db,'main',$language);if(!empty($GLOBALS['ivr_channel_hungup'])){$ended=true;break;}if($digit==='')continue;
            $q=$db->prepare('SELECT action_key FROM ivr_menu_options WHERE menu_key="main" AND language=? AND digit=? AND is_active=1');$q->execute([$language,$digit]);$action=(string)($q->fetchColumn()?:'');event($db,$callId,$action?'menu_selected':'invalid_input','main',$action?:$digit);
            if($action==='hangup'){$ended=true;break;}
            if($action==='repeat')continue;
            if($action==='emergency'){$db->prepare("UPDATE ivr_calls SET state='emergency',current_menu='emergency' WHERE ivr_call_id=?")->execute([$callId]);$ed=get_digit($db,'emergency',$language,15000);if($ed==='1'){$db->prepare("INSERT INTO ivr_emergency_escalations(ivr_call_id,signal_key) VALUES(?,'caller_requested_test_escalation')")->execute([$callId]);event($db,$callId,'emergency_test_escalation','emergency','caller_requested_test_escalation',['message'=>'Test escalation recorded; no notification sent.']);get_digit($db,'emergency_instruction',$language,6000);}if(!empty($GLOBALS['ivr_channel_hungup'])){$ended=true;break;}$db->prepare("UPDATE ivr_calls SET state='main_menu',current_menu='main' WHERE ivr_call_id=?")->execute([$callId]);continue;}
            if($action==='queue'){$db->prepare("INSERT INTO ivr_call_queue(ivr_call_id) VALUES(?) ON DUPLICATE KEY UPDATE queue_status='waiting',queued_at=CURRENT_TIMESTAMP,resolved_at=NULL")->execute([$callId]);$db->prepare("UPDATE ivr_calls SET status='queued',state='queue_waiting',current_menu='main' WHERE ivr_call_id=?")->execute([$callId]);event($db,$callId,'queue_entered','queue',null,['message'=>'Waiting for a simulated worker action in the administration dashboard.']);$queueDigit=get_digit($db,'queue',$language,20000);$queueQ=$db->prepare('SELECT queue_status,queued_at FROM ivr_call_queue WHERE ivr_call_id=?');$queueQ->execute([$callId]);$queueState=$queueQ->fetch(PDO::FETCH_ASSOC);if($queueState&&$queueState['queue_status']==='answered'){$waitQ=$db->prepare('SELECT TIMESTAMPDIFF(SECOND,?,NOW())');$waitQ->execute([$queueState['queued_at']]);$db->prepare("UPDATE ivr_calls SET status='answered_simulated',state='queue_answered',waiting_seconds=? WHERE ivr_call_id=?")->execute([(int)$waitQ->fetchColumn(),$callId]);}elseif($queueDigit==='8'){if($queueState&&$queueState['queue_status']==='waiting')$db->prepare("UPDATE ivr_call_queue SET queue_status='cancelled',resolved_at=NOW() WHERE ivr_call_id=? AND queue_status='waiting'")->execute([$callId]);$db->prepare("UPDATE ivr_calls SET status='active',state='main_menu' WHERE ivr_call_id=?")->execute([$callId]);}else{$db->prepare("UPDATE ivr_calls SET status='active',state='main_menu' WHERE ivr_call_id=?")->execute([$callId]);}if(!empty($GLOBALS['ivr_channel_hungup'])){$ended=true;break;}continue;}
            if($action==='pregnancy_info'||$action==='nutrition'){$db->prepare("UPDATE ivr_calls SET state='education',current_menu='education' WHERE ivr_call_id=?")->execute([$callId]);$submenu=get_digit($db,'education',$language);$option=$db->prepare('SELECT action_key FROM ivr_menu_options WHERE menu_key="education" AND language=? AND digit=? AND is_active=1');$option->execute([$language,$submenu]);$educationAction=(string)($option->fetchColumn()?:'');if($educationAction==='back'){$db->prepare("UPDATE ivr_calls SET state='main_menu',current_menu='main' WHERE ivr_call_id=?")->execute([$callId]);continue;}if(preg_match('/^trimester_(1|2|3|all)$/',$educationAction,$matches)){$tri=$matches[1]==='all'?null:(int)$matches[1];$items=ivr_get_education($db,$language,$tri,$action==='nutrition'?'nutrition':'pregnancy');$summary=$items?implode(' | ',array_map(static fn($x)=>$x['title'],$items)):'No approved published content found for this language and stage.';event($db,$callId,'content_retrieved','education',$educationAction,['content_titles'=>$summary]);get_digit($db,'education',$language,6000);}$db->prepare("UPDATE ivr_calls SET state='main_menu',current_menu='main' WHERE ivr_call_id=?")->execute([$callId]);if(!empty($GLOBALS['ivr_channel_hungup'])){$ended=true;break;}continue;}
            if($action==='appointment'||$action==='medication'){$type=$action==='appointment'?'appointment':'medication_reminder';$infoQ=$db->prepare('SELECT label_en,label_rw,details_en,details_rw,scheduled_at FROM ivr_test_fixture_data WHERE fixture_key="synthetic_anonymous" AND data_type=?');$infoQ->execute([$type]);$info=$infoQ->fetch(PDO::FETCH_ASSOC);$message=$info?($language==='rw'?$info['label_rw'].' '.$info['details_rw']:$info['label_en'].' '.$info['details_en']):'No synthetic test information is configured. No patient record queried.';event($db,$callId,$action.'_lookup','main','synthetic_only',['message'=>$message]);get_digit($db,$action,$language,6000);if(!empty($GLOBALS['ivr_channel_hungup'])){$ended=true;break;}continue;}
        }
        if($turn>=60)$ended=true;
    }
}catch(Throwable $exception){error_log('M-CARE local IVR AGI error: '.$exception->getMessage());$db->prepare("UPDATE ivr_calls SET status='failed',state='failed',error_message='Local AGI processing error',ended_at=NOW(),duration_seconds=TIMESTAMPDIFF(SECOND,started_at,NOW()) WHERE ivr_call_id=?")->execute([$callId]);event($db,$callId,'call_failed','agi','processing_error');$ended=true;}
if($ended){$db->prepare("UPDATE ivr_calls SET status='completed',state='completed',current_menu='ended',ended_at=NOW(),duration_seconds=TIMESTAMPDIFF(SECOND,started_at,NOW()) WHERE ivr_call_id=? AND status<>'failed'")->execute([$callId]);$db->prepare("UPDATE ivr_call_queue SET queue_status='cancelled',resolved_at=NOW() WHERE ivr_call_id=? AND queue_status='waiting'")->execute([$callId]);event($db,$callId,'call_ended','agi','hangup');}
agi('HANGUP');
